-- Generated by python -m generators.weather_associations. Read-only; does not create links.
IF @@SERVERNAME<>N'BVirtualPC' OR DB_NAME()<>N'EEMSuite_Northlake'
    THROW 51000, 'This check targets BVirtualPC / EEMSuite_Northlake.', 1;
DECLARE @Expected nvarchar(max)=N'[{"Station":"KSAC","Source":"KSAC Outside Air Temperature","Target":"KSAC Forecast Temperature","MeasureType":"Temperature","SourceUnit":"Degrees Fahrenheit","TargetUnit":"Degrees Fahrenheit"},{"Station":"KSAC","Source":"KSAC Relative Humidity","Target":"KSAC Forecast Relative Humidity","MeasureType":"Relative Humidity","SourceUnit":"Percent","TargetUnit":"Percent"},{"Station":"KSAC","Source":"KSAC Wind Speed","Target":"KSAC Forecast Wind Speed","MeasureType":"Wind Speed","SourceUnit":"Miles per Hour","TargetUnit":"Miles per Hour"},{"Station":"KSMF","Source":"KSMF Outside Air Temperature","Target":"KSMF Forecast Temperature","MeasureType":"Temperature","SourceUnit":"Degrees Centigrade","TargetUnit":"Degrees Fahrenheit"},{"Station":"KSMF","Source":"KSMF Wind Speed","Target":"KSMF Forecast Wind Speed","MeasureType":"Wind Speed","SourceUnit":"Kilometers per Hour","TargetUnit":"Kilometers per Hour"},{"Station":"KSUU","Source":"KSUU Outside Air Temperature","Target":"KSUU Forecast Temperature","MeasureType":"Temperature","SourceUnit":"Degrees Centigrade","TargetUnit":"Degrees Centigrade"},{"Station":"KSUU","Source":"KSUU Wind Speed","Target":"KSUU Forecast Wind Speed","MeasureType":"Wind Speed","SourceUnit":"Knots","TargetUnit":"Knots"},{"Station":"KSUU","Source":"KSUU Dew Point","Target":"KSUU Forecast Dew Point","MeasureType":"Dew Point","SourceUnit":"Degrees Centigrade","TargetUnit":"Degrees Centigrade"},{"Station":"KSAC","Source":"KSAC Dew Point","Target":"KSAC Forecast Dew Point","MeasureType":"Dew Point","SourceUnit":"Degrees Fahrenheit","TargetUnit":"Degrees Fahrenheit"},{"Station":"KSMF","Source":"KSMF Dew Point","Target":"KSMF Forecast Dew Point","MeasureType":"Dew Point","SourceUnit":"Degrees Centigrade","TargetUnit":"Degrees Centigrade"},{"Station":"KSMF","Source":"KSMF Relative Humidity","Target":"KSMF Forecast Relative Humidity","MeasureType":"Relative Humidity","SourceUnit":"Percent","TargetUnit":"Percent"},{"Station":"KSUU","Source":"KSUU Relative Humidity","Target":"KSUU Forecast Relative Humidity","MeasureType":"Relative Humidity","SourceUnit":"Percent","TargetUnit":"Percent"}]';
SELECT e.Station,e.Source,e.Target,e.MeasureType,source.PtID AS SourcePtID,target.PtID AS ForecastPtID,
    CASE WHEN source.PtID IS NULL OR target.PtID IS NULL THEN N'Missing point'
         WHEN r.PtID IS NULL THEN N'Missing Association'
         WHEN smt.MT_MeasureName IS NULL OR tmt.MT_MeasureName IS NULL OR smt.MT_MeasureName<>e.MeasureType OR tmt.MT_MeasureName<>e.MeasureType THEN N'Incorrect measurement type'
         WHEN su.UN_Name IS NULL OR tu.UN_Name IS NULL OR su.UN_Name<>e.SourceUnit OR tu.UN_Name<>e.TargetUnit OR target.Interval<>60 THEN N'Incorrect unit or forecast interval'
         WHEN target.PtGatewayID IS NULL OR source.PtGatewayID IS NULL THEN N'Missing gateway'
         WHEN EXISTS(SELECT 1 FROM dbo.PointBaseline b WHERE b.PtID=target.PtID) THEN N'Forecast incorrectly configured as baseline'
         ELSE N'Configured' END AS Result
FROM OPENJSON(@Expected) WITH(Station nvarchar(32),Source nvarchar(64),Target nvarchar(64),MeasureType nvarchar(64),SourceUnit nvarchar(64),TargetUnit nvarchar(64)) e
LEFT JOIN dbo.Meter m ON m.SM_Code=e.Station
LEFT JOIN dbo.MetaWorld_TBL sw ON sw.ParentID=m.MetaWorldID AND sw.Description=e.Source
LEFT JOIN dbo.PointDef_TBL source ON source.MetaWorldID=sw.MetaWorldID
LEFT JOIN dbo.MetaWorld_TBL tw ON tw.ParentID=m.MetaWorldID AND tw.Description=e.Target
LEFT JOIN dbo.PointDef_TBL target ON target.MetaWorldID=tw.MetaWorldID
LEFT JOIN dbo.MeasureType smt ON smt.MT_MeasureTypeID=source.MT_MeasureTypeID
LEFT JOIN dbo.MeasureType tmt ON tmt.MT_MeasureTypeID=target.MT_MeasureTypeID
LEFT JOIN dbo.Unit su ON su.UN_UnitID=source.UN_UnitID
LEFT JOIN dbo.Unit tu ON tu.UN_UnitID=target.UN_UnitID
LEFT JOIN dbo.PtRelatedData_TBL r ON r.PtID=source.PtID AND r.RelatedPtID=target.PtID
    AND r.ReasonType=N'V' AND r.RelationshipKind=N'Association'
ORDER BY e.Station,e.Source;
